#include "tensorflow/lite/kernels/kernel_util.h"
#include "tensorflow/lite/micro/kernels/kernel_util.h"

namespace tflite {
namespace cmsis_nn {
namespace {

cmsis_nn_dims ToCmsisDims(const TfLiteTensor* tensor) {
  return {tensor->dims->data[0], tensor->dims->data[1], tensor->dims->data[2],
          tensor->dims->data[3]};
}

}  // namespace

TfLiteStatus PrepareConvF32(
    TfLiteContext* context, const TfLiteConvParams& params,
    const TfLiteTensor* input, const TfLiteTensor* filter,
    const TfLiteTensor* bias, const TfLiteTensor* output,
    const OpDataConv& reference_op_data, ConvF32State* state) {
  state->enabled = false;
  state->scratch_buffer_index = -1;
  state->scratch_buffer_size = 0;

  // PrepareConvF32 is called for every input type; only float32 is CMSIS-NN's.
  if (input->type != kTfLiteFloat32 || filter->type != kTfLiteFloat32 ||
      (bias != nullptr && bias->type != kTfLiteFloat32)) {
    return kTfLiteOk;
  }

  // CMSIS-NN float conv is the standard (non-grouped) path only.
  if (input->dims->data[3] != filter->dims->data[3]) {
    return kTfLiteOk;
  }

  const int output_channels = output->dims->data[3];

  state->params = {};
  state->params.stride.h = params.stride_height;
  state->params.stride.w = params.stride_width;
  state->params.padding.h = reference_op_data.padding.height;
  state->params.padding.w = reference_op_data.padding.width;
  state->params.dilation.h = params.dilation_height_factor;
  state->params.dilation.w = params.dilation_width_factor;
  CalculateActivationRange(params.activation, &state->params.activation.min,
                           &state->params.activation.max);
  state->params.weight_format = ARM_NN_WEIGHT_FORMAT_STANDARD;

  state->input_dims = ToCmsisDims(input);
  state->filter_dims = ToCmsisDims(filter);
  state->bias_dims = {1, 1, 1, output_channels};
  state->output_dims = ToCmsisDims(output);

  const int32_t scratch_size = arm_convolve_wrapper_f32_get_buffer_size(
      &state->params, &state->input_dims, &state->filter_dims,
      &state->output_dims);
  if (scratch_size < 0) {
    return kTfLiteOk;
  }
  if (scratch_size > 0) {
    int scratch_buffer_index = -1;
    if (context->RequestScratchBufferInArena(
            context, scratch_size, &scratch_buffer_index) != kTfLiteOk) {
      return kTfLiteOk;
    }
    state->scratch_buffer_index = scratch_buffer_index;
  }
  state->scratch_buffer_size = scratch_size;
  state->enabled = true;
  return kTfLiteOk;
}

bool EvalConvF32(TfLiteContext* context, const TfLiteEvalTensor* input,
                 const TfLiteEvalTensor* filter, const TfLiteEvalTensor* bias,
                 TfLiteEvalTensor* output, const ConvF32State& state) {
  if (!state.enabled) {
    return false;
  }

  void* scratch = nullptr;
  if (state.scratch_buffer_size > 0) {
    scratch = context->GetScratchBuffer(context, state.scratch_buffer_index);
  }

  cmsis_nn_context cmsis_context = {};
  cmsis_context.buf = scratch;
  cmsis_context.size = state.scratch_buffer_size;

  const arm_cmsis_nn_status status = arm_convolve_wrapper_f32(
      &cmsis_context, &state.params, &state.input_dims,
      tflite::micro::GetTensorData<float>(input), &state.filter_dims,
      tflite::micro::GetTensorData<float>(filter), &state.bias_dims,
      tflite::micro::GetOptionalTensorData<float>(bias), &state.output_dims,
      tflite::micro::GetTensorData<float>(output));

  return status == ARM_CMSIS_NN_SUCCESS;
}

}  // namespace cmsis_nn
}  // namespace tflite
#endif  // CMSIS_NN

