73	  float min_val = input[0];
74	  float max_val = input[0];
75	  for (int i = 1; i < size; ++i) {
76	    if (input[i] < min_val) min_val = input[i];
77	    if (input[i] > max_val) max_val = input[i];
78	  }
79	  const float range = std::max(std::abs(min_val), std::abs(max_val));
